function buildCommand() {
  const __args = [['robotscheck'], 'Network Tools', 'Show a site\'s robots.txt', async ({ sock, from, msg, args }) => {
  const url = args[0];
  if (!url) return sock.sendMessage(from, { text: 'Usage: .robotscheck https://example.com' }, { quoted: msg });
  try {
    const res = await fetch(url.replace(/\/$/, '') + '/robots.txt');
    const text = await res.text();
    await sock.sendMessage(from, { text: text.slice(0, 1500) || 'Empty robots.txt' }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Could not fetch robots.txt.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
